public class Solution {
    static class SegmentTree {
        private final long[] tree;
        private final long[] lazy;
        private final int n;

        SegmentTree(long[] valores) {
            if (valores == null || valores.length == 0) {
                throw new IllegalArgumentException("array vazio");
            }
            n = valores.length;
            tree = new long[4 * n];
            lazy = new long[4 * n];
            build(1, 0, n - 1, valores);
        }

        void add(int esquerda, int direita, long delta) {
            validar(esquerda, direita);
            update(1, 0, n - 1, esquerda, direita, delta);
        }

        long sum(int esquerda, int direita) {
            validar(esquerda, direita);
            return query(1, 0, n - 1, esquerda, direita);
        }

        private void validar(int l, int r) {
            if (l < 0 || r >= n || l > r) throw new IllegalArgumentException("intervalo invalido");
        }

        private void build(int no, int l, int r, long[] valores) {
            if (l == r) {
                tree[no] = valores[l];
                return;
            }
            int m = (l + r) / 2;
            build(2 * no, l, m, valores);
            build(2 * no + 1, m + 1, r, valores);
            tree[no] = tree[2 * no] + tree[2 * no + 1];
        }

        private void apply(int no, int l, int r, long delta) {
            tree[no] += delta * (r - l + 1L);
            lazy[no] += delta;
        }

        private void push(int no, int l, int r) {
            if (lazy[no] == 0) return;
            int m = (l + r) / 2;
            apply(2 * no, l, m, lazy[no]);
            apply(2 * no + 1, m + 1, r, lazy[no]);
            lazy[no] = 0;
        }

        private void update(int no, int l, int r, int ql, int qr, long delta) {
            if (qr < l || r < ql) return;
            if (ql <= l && r <= qr) {
                apply(no, l, r, delta);
                return;
            }
            push(no, l, r);
            int m = (l + r) / 2;
            update(2 * no, l, m, ql, qr, delta);
            update(2 * no + 1, m + 1, r, ql, qr, delta);
            tree[no] = tree[2 * no] + tree[2 * no + 1];
        }

        private long query(int no, int l, int r, int ql, int qr) {
            if (qr < l || r < ql) return 0;
            if (ql <= l && r <= qr) return tree[no];
            push(no, l, r);
            int m = (l + r) / 2;
            return query(2 * no, l, m, ql, qr)
                 + query(2 * no + 1, m + 1, r, ql, qr);
        }
    }
}

