import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void somaComAtualizacaoDeIntervalo() {
        var st = new Solution.SegmentTree(new long[]{1,2,3,4,5});
        st.add(1, 3, 10);
        assertEquals(39, st.sum(1, 3));
        assertEquals(45, st.sum(0, 4));
        assertEquals(1, st.sum(0, 0));
    }

    @Test void deltaNegativo() {
        var st = new Solution.SegmentTree(new long[]{10,10,10,10});
        st.add(0, 1, -5);
        assertEquals(10, st.sum(0, 3));
        assertEquals(5, st.sum(0, 0));
    }

    @Test void atualizacoesSobrepostas() {
        var st = new Solution.SegmentTree(new long[]{0,0,0,0,0});
        st.add(0, 4, 1);
        st.add(1, 3, 2);
        assertEquals(5, st.sum(0, 0));
        assertEquals(3, st.sum(1, 1));
        assertEquals(3, st.sum(2, 3));
    }

    @Test void umElemento() {
        var st = new Solution.SegmentTree(new long[]{7});
        st.add(0, 0, 3);
        assertEquals(10, st.sum(0, 0));
    }

    @Test void intervalosInvalidos() {
        var st = new Solution.SegmentTree(new long[]{1,2});
        assertThrows(IllegalArgumentException.class, () -> st.add(-1, 1, 5));
        assertThrows(IllegalArgumentException.class, () -> st.sum(1, 0));
        assertThrows(IllegalArgumentException.class, () -> st.sum(0, 2));
    }
}
